INSERT OR IGNORE INTO ayah (surah, ayah, text_en, source) VALUES
(3, 134, 'Who spend in ease and hardship, who restrain anger and pardon people. Allah loves those who do good.', 'Sahih International'),
(4, 135, 'O you who believe, be persistently standing firm in justice, witnesses for Allah, even if it be against yourselves or parents and relatives.', 'Sahih International'),
(5, 8, 'Be persistently standing firm for Allah, witnesses in justice, and do not let hatred of a people prevent you from being just. Be just; that is nearer to righteousness.', 'Sahih International'),
(16, 90, 'Indeed, Allah orders justice and good conduct and giving to relatives and forbids immorality and bad conduct and oppression.', 'Sahih International'),
(17, 53, 'Tell My servants to say that which is best. Indeed, Satan induces among them discord.', 'Sahih International'),
(24, 22, 'Let them pardon and overlook. Would you not like that Allah should forgive you?', 'Sahih International'),
(41, 34, 'Repel evil by that which is better; then the one between whom and you was enmity will become as though he was a devoted friend.', 'Sahih International'),
(49, 12, 'Avoid much suspicion. Do not spy or backbite each other. Would one of you like to eat the flesh of his brother dead?', 'Sahih International');
